    "roadmap_title": {
      "type": "Text",
      "props": {
        "text": "Path to Senior Data Scientist: 3-Year Roadmap",
        "variant": "h1"
      },
      "children": []
    },
    "roadmap_intro_text": {
      "type": "Text",
      "props": {
        "text": "This roadmap outlines a structured approach to transition from a Junior Software Developer to a Senior Data Scientist within three years, leveraging your existing Python and basic SQL skills. The plan focuses on building expertise in machine learning, advanced statistics, and data visualization, complemented by practical portfolio projects."
      },
      "children": []
    },
    "skill_dev_title": {
      "type": "Text",
      "props": {
        "text": "Skill Development & Portfolio Roadmap",
        "variant": "h2"
      },
      "children": []
    },
    "skill_dev_intro_text": {
      "type": "Text",
      "props": {
        "text": "This phased approach will guide your learning and project development over the next three years, culminating in the skills and experience required for a Senior Data Scientist role."
      },
      "children": []
    },
    "year1_card": {
      "type": "Card",
      "props": {
        "padding": 16
      },
      "children": [
        "year1_header_stack",
        "year1_goal",
