        "name": "../assets/r_000597_01_1_book.svg"
      },
      "children": []
    },
    "year1_title": {
      "type": "Text",
      "props": {
        "text": "Year 1: Foundations & Core Data Science",
        "variant": "h3"
      },
      "children": []
    },
    "year1_goal": {
      "type": "Text",
      "props": {
        "text": "Goal: Establish a robust foundation in statistics, advanced programming for data science, and initial machine learning concepts."
      },
      "children": []
    },
    "year1_learning_title": {
      "type": "Text",
      "props": {
        "text": "Key Learning & Resources:"
      },
      "children": []
    },
    "year1_learning_list": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm",
        "paddingHorizontal": 16
      },
      "children": [
        "year1_learning_item1",
        "year1_learning_item2",
        "year1_learning_item3",
        "year1_learning_item4"
      ]
    },
    "year1_learning_item1": {
      "type": "Text",
      "props": {
        "text": "Advanced Python for Data Science: Master Pandas, NumPy for data manipulation and analysis; Scikit-learn for basic ML."
      },
      "children": []
    },
    "year1_learning_item2": {
      "type": "Text",
      "props": {
        "text": "Statistics & Probability: Deepen understanding of descriptive and inferential statistics, hypothesis testing, regression."
      },
      "children": []
    },
    "year1_learning_item3": {
      "type": "Text",
      "props": {
        "text": "Advanced SQL: Practice complex queries, window functions, database design, and optimization for data extraction and preparation."
      },
      "children": []
    },
    "year1_learning_item4": {
      "type": "Text",
      "props": {
        "text": "Data Visualization Fundamentals: Learn to create informative and aesthetic plots using Matplotlib, Seaborn, and an introduction to interactive tools like Plotly."
      },
      "children": []
    },
    "year1_courses_title": {
      "type": "Text",
      "props": {
        "text": "Suggested Courses:"
      },
      "children": []
    },
    "year1_courses_console": {
      "type": "ConsoleLog",
      "props": {
        "code": "Python for Data Science and Machine Learning Bootcamp (Udemy)\nStatistics with Python (Coursera)\nSQL for Data Analysis (Mode Analytics Tutorial)",
        "language": "text"
      },
      "children": []
    },
    "year1_projects_title": {
      "type": "Text",
      "props": {
        "text": "Portfolio Projects:"
      },
      "children": []
    },
    "year1_projects_list": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm",
        "paddingHorizontal": 16
      },
      "children": [
        "year1_projects_item1",
        "year1_projects_item2",
        "year1_projects_item3"
      ]
    },
    "year1_projects_item1": {
      "type": "Text",
      "props": {
        "text": "Exploratory Data Analysis (EDA): Perform comprehensive EDA on at least two public datasets (e.g., from Kaggle), identifying patterns and insights."
      },
      "children": []
    },
    "year1_projects_item2": {
      "type": "Text",
      "props": {
        "text": "Basic Machine Learning Model: Implement a simple linear or logistic regression model from scratch or using Scikit-learn on a clean dataset."
      },
      "children": []
    },
    "year1_projects_item3": {
      "type": "Text",
      "props": {
        "text": "Data Cleaning & Visualization: Take a messy, real-world dataset, clean it thoroughly, and create a series of compelling visualizations to tell a story."
      },
      "children": []
    },
    "year2_card": {
      "type": "Card",
      "props": {
        "padding": 16
      },
      "children": [
        "year2_header_stack",
        "year2_goal",
