    "year2_title": {
      "type": "Text",
      "props": {
        "text": "Year 2: Deep Dive into Machine Learning & Advanced Analytics",
        "variant": "h3"
      },
      "children": []
    },
    "year2_goal": {
      "type": "Text",
      "props": {
        "text": "Goal: Master a wide range of machine learning algorithms, understand model evaluation, and apply advanced analytical techniques."
      },
      "children": []
    },
    "year2_learning_title": {
      "type": "Text",
      "props": {
        "text": "Key Learning & Resources:"
      },
      "children": []
    },
    "year2_learning_list": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm",
        "paddingHorizontal": 16
      },
      "children": [
        "year2_learning_item1",
        "year2_learning_item2",
        "year2_learning_item3",
        "year2_learning_item4"
      ]
    },
    "year2_learning_item1": {
      "type": "Text",
      "props": {
        "text": "Machine Learning Algorithms: Study supervised learning (SVMs, Decision Trees, Random Forests, Gradient Boosting), unsupervised learning (Clustering algorithms), and ensemble methods."
      },
      "children": []
    },
    "year2_learning_item2": {
      "type": "Text",
      "props": {
        "text": "Deep Learning Fundamentals: Learn neural networks, CNNs, and RNNs using frameworks like Keras, TensorFlow, or PyTorch."
      },
      "children": []
    },
    "year2_learning_item3": {
      "type": "Text",
      "props": {
        "text": "Experimental Design & Causal Inference: Understand A/B testing methodologies, statistical power, and basic causal inference techniques."
      },
      "children": []
    },
    "year2_learning_item4": {
      "type": "Text",
      "props": {
        "text": "Feature Engineering & Model Evaluation: Develop skills in creating effective features and rigorously evaluating model performance (metrics, cross-validation)."
      },
      "children": []
    },
    "year2_courses_title": {
      "type": "Text",
      "props": {
        "text": "Suggested Courses:"
      },
      "children": []
    },
    "year2_courses_console": {
      "type": "ConsoleLog",
      "props": {
        "code": "Machine Learning (Stanford/Coursera by Andrew Ng)\nDeep Learning Specialization (Coursera)\nPractical Statistics for Data Scientists (O'Reilly book)",
        "language": "text"
      },
      "children": []
    },
    "year2_projects_title": {
      "type": "Text",
      "props": {
        "text": "Portfolio Projects:"
      },
      "children": []
    },
    "year2_projects_list": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm",
        "paddingHorizontal": 16
      },
      "children": [
        "year2_projects_item1",
        "year2_projects_item2",
        "year2_projects_item3"
      ]
    },
    "year2_projects_item1": {
      "type": "Text",
      "props": {
        "text": "End-to-End ML Project: Develop a complete machine learning solution, from data ingestion and preprocessing to model training, evaluation, and interpretation."
      },
      "children": []
    },
    "year2_projects_item2": {
      "type": "Text",
      "props": {
        "text": "Deep Learning Application: Build an image classification, object detection, or natural language processing (NLP) model using a deep learning framework."
      },
      "children": []
    },
    "year2_projects_item3": {
      "type": "Text",
      "props": {
        "text": "A/B Testing Analysis: Design and simulate an A/B test, then analyze the results to determine statistical significance and business impact."
      },
      "children": []
    },
