    "year3_title": {
      "type": "Text",
      "props": {
        "text": "Year 3: Specialization, Deployment & Senior Impact",
        "variant": "h3"
      },
      "children": []
    },
    "year3_goal": {
      "type": "Text",
      "props": {
        "text": "Goal: Specialize in a particular ML domain, gain practical experience in MLOps, deployment, and cultivate leadership and communication skills."
      },
      "children": []
    },
    "year3_learning_title": {
      "type": "Text",
      "props": {
        "text": "Key Learning & Resources:"
      },
      "children": []
    },
    "year3_learning_list": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm",
        "paddingHorizontal": 16
      },
      "children": [
        "year3_learning_item1",
        "year3_learning_item2",
        "year3_learning_item3",
        "year3_learning_item4",
        "year3_learning_item5",
        "year3_learning_item6"
      ]
    },
    "year3_learning_item1": {
      "type": "Text",
      "props": {
        "text": "ML Specialization: Choose one area to deep-dive into (e.g., Natural Language Processing, Computer Vision, Time Series Analysis, Reinforcement Learning)."
      },
      "children": []
    },
    "year3_learning_item2": {
      "type": "Text",
      "props": {
        "text": "MLOps & Deployment: Learn about Docker for containerization, basic Kubernetes for orchestration, and how to deploy models using cloud platforms (e.g., AWS SageMaker, Google AI Platform, Azure ML)."
      },
      "children": []
    },
    "year3_learning_item3": {
      "type": "Text",
      "props": {
        "text": "Big Data Technologies: Gain foundational knowledge of distributed computing concepts and tools like Apache Spark."
      },
      "children": []
    },
    "year3_learning_item4": {
      "type": "Text",
      "props": {
        "text": "Ethics in AI & Responsible AI: Understand the ethical implications of AI and best practices for building fair and transparent models."
      },
      "children": []
    },
    "year3_learning_item5": {
      "type": "Text",
      "props": {
        "text": "Communication & Leadership: Practice presenting complex technical findings to non-technical audiences, mentoring junior colleagues, and leading data science initiatives."
      },
      "children": []
    },
    "year3_learning_item6": {
      "type": "Text",
      "props": {
        "text": "Suggested Certifications:"
      },
      "children": []
    },
