      "type": "Text",
      "props": {
        "text": "Suggested Certifications:"
      },
      "children": []
    },
    "year3_certs_console": {
      "type": "ConsoleLog",
      "props": {
        "code": "AWS Certified Machine Learning – Specialty\nGoogle Cloud Professional Data Engineer",
        "language": "text"
      },
      "children": []
    },
    "year3_projects_title": {
      "type": "Text",
      "props": {
        "text": "Portfolio Projects:"
      },
      "children": []
    },
    "year3_projects_list": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm",
        "paddingHorizontal": 16
      },
      "children": [
        "year3_projects_item1",
        "year3_projects_item2",
        "year3_projects_item3"
      ]
    },
    "year3_projects_item1": {
      "type": "Text",
      "props": {
        "text": "Model Deployment: Deploy an ML model as a web service (e.g., using Flask/Streamlit) to a cloud platform, demonstrating MLOps principles."
      },
      "children": []
    },
    "year3_projects_item2": {
      "type": "Text",
      "props": {
        "text": "Advanced Specialization Project: Create a sophisticated application in your chosen specialization (e.g., a custom chatbot, a complex recommendation system, a real-time anomaly detection system)."
      },
      "children": []
    },
    "year3_projects_item3": {
      "type": "Text",
      "props": {
        "text": "Project Leadership & Documentation: Lead a data science project (personal or open-source contribution), meticulously"
      },
      "children": []
    }
  }
